import {
  Mjml,
  MjmlBody,
  MjmlButton,
  MjmlColumn,
  MjmlFont,
  MjmlHead,
  MjmlImage,
  MjmlPreview,
  MjmlSection,
  MjmlSpacer,
  MjmlText,
  MjmlWrapper,
} from "@faire/mjml-react";

import type { EmailTheme } from "@/components/email/email-theme";
import { emailAsset } from "@/components/email/email-assets";
import { defaultTheme } from "@/components/email/theme-default";

export type CardCouponsVariant =
  | "with-name"
  | "with-pattern"
  | "with-overlay"
  | "with-background-image"
  | "background-image-header";

export interface CardCouponsProps {
  theme?: EmailTheme;
  heading?: string;
  recipient?: string;
  code?: string;
  description?: string;
  logoSrc?: string;
  logoAlt?: string;
  backgroundImageSrc?: string;
  buttonLabel?: string;
  buttonHref?: string;
  arrowIconSrc?: string;
  pageBackgroundColor?: string;
  backgroundColor?: string;
  cardBackgroundColor?: string;
  codeBackgroundColor?: string;
  headingColor?: string;
  textColor?: string;
  mutedTextColor?: string;
  buttonBackgroundColor?: string;
  buttonColor?: string;
  variant?: CardCouponsVariant;
}

const fontFamily =
  'Inter, ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif';

const backgrounds: Partial<Record<CardCouponsVariant, string>> = {
  "background-image-header": emailAsset("coupons/bg-image-3.jpg"),
  "with-background-image": emailAsset("coupons/bg-image-2.jpg"),
  "with-overlay": emailAsset("coupons/bg-image-1.jpg"),
  "with-pattern": emailAsset("coupons/pattern.png"),
};

export const CardCouponsSection = (props: Omit<CardCouponsProps, "theme">) => {
  const {
    heading,
    recipient,
    code,
    description,
    logoSrc,
    logoAlt,
    backgroundImageSrc,
    buttonLabel,
    buttonHref,
    backgroundColor,
    cardBackgroundColor,
    codeBackgroundColor,
    headingColor,
    textColor,
    mutedTextColor,
    buttonBackgroundColor,
    buttonColor,
    variant,
  } = {
    backgroundColor: "#fffffe",
    buttonBackgroundColor: "#4f46e5",
    buttonColor: "#fffffe",
    buttonHref: "https://example.com",
    buttonLabel: "Shop now",
    cardBackgroundColor: "#030712",
    code: "WINTER20OFF",
    codeBackgroundColor: "#f3f4f6",
    description:
      "Use code: WINTER20OFF at checkout, or click the link below to automatically apply the discount to your order.",
    headingColor: "#fffffe",
    logoAlt: "Brand",
    mutedTextColor: "#9ca3af",
    recipient: "Jenna Adams",
    textColor: "#4b5563",
    variant: "with-overlay" as CardCouponsVariant,
    ...props,
  };
  const resolvedHeading =
    heading ??
    (variant === "with-background-image" || variant === "with-overlay"
      ? "An extra 20% OFF"
      : "Just for you - 20% OFF");
  const resolvedLogo =
    logoSrc ??
    (variant === "with-name"
      ? emailAsset("maizzle-insignia.png")
      : emailAsset("maizzle-insignia-light-lg.png"));
  const showDescription = [
    "with-name",
    "with-pattern",
    "with-overlay",
  ].includes(variant);
  return (
    <>
      <MjmlSection
        backgroundColor={cardBackgroundColor}
        backgroundUrl={backgroundImageSrc ?? backgrounds[variant]}
        borderRadius="8px"
        padding="44px 64px"
      >
        <MjmlColumn padding="0" width="400px">
          <MjmlImage
            alt={logoAlt}
            padding="0"
            src={resolvedLogo}
            width="104px"
          />
          <MjmlSpacer height="32px" />
          {variant === "with-name" ? (
            <MjmlText
              align="center"
              color={mutedTextColor}
              fontFamily={fontFamily}
              fontSize="16px"
              lineHeight="24px"
              padding="0"
            >
              {recipient}
            </MjmlText>
          ) : null}
          <MjmlText
            align="center"
            color={headingColor}
            fontFamily={fontFamily}
            fontSize="28px"
            fontWeight="700"
            lineHeight="36px"
            padding="16px 0 0"
          >
            {resolvedHeading}
          </MjmlText>
          <MjmlSpacer height="24px" />
          <MjmlText
            align="center"
            color="#030712"
            containerBackgroundColor={codeBackgroundColor}
            fontFamily={fontFamily}
            fontSize="18px"
            fontWeight="600"
            lineHeight="24px"
            padding="12px 18px"
          >
            {code}
          </MjmlText>
        </MjmlColumn>
      </MjmlSection>
      <MjmlSection backgroundColor={backgroundColor} padding="24px 64px 44px">
        <MjmlColumn padding="0">
          {showDescription ? (
            <>
              <MjmlText
                align="center"
                color={textColor}
                fontFamily={fontFamily}
                fontSize="16px"
                lineHeight="24px"
                padding="0"
              >
                {description}
              </MjmlText>
              <MjmlSpacer height="44px" />
            </>
          ) : null}
          <MjmlButton
            backgroundColor={buttonBackgroundColor}
            borderRadius="8px"
            color={buttonColor}
            fontFamily={fontFamily}
            fontSize="16px"
            fontWeight="500"
            href={buttonHref}
            innerPadding="14px 20px"
            lineHeight="16px"
            padding="0"
          >
            {buttonLabel} →
          </MjmlButton>
        </MjmlColumn>
      </MjmlSection>
    </>
  );
};

export const CardCoupons = ({
  pageBackgroundColor = "#f1f5f9",
  theme = defaultTheme,
  variant = "with-overlay",
  ...props
}: CardCouponsProps) => (
  <Mjml>
    <MjmlHead>
      <MjmlPreview>An extra 20% OFF</MjmlPreview>
      <MjmlFont href="https://rsms.me/inter/inter.css" name="Inter" />
    </MjmlHead>
    <MjmlBody
      backgroundColor={pageBackgroundColor}
      width={theme.containerWidth}
    >
      <MjmlWrapper padding="0">
        <CardCouponsSection
          {...props}
          pageBackgroundColor={pageBackgroundColor}
          variant={variant}
        />
      </MjmlWrapper>
    </MjmlBody>
  </Mjml>
);

CardCoupons.PreviewProps = {
  theme: defaultTheme,
  variant: "with-overlay",
} satisfies CardCouponsProps;

const ASSET_ORIGIN = "https://www.emailcn.run";

const palettes = [
  ["4F46E5", "FFFFFF"],
  ["0F766E", "FFFFFF"],
  ["C2410C", "FFFFFF"],
  ["7E22CE", "FFFFFF"],
  ["0369A1", "FFFFFF"],
  ["BE123C", "FFFFFF"],
] as const;

const hashString = (value: string) => {
  let hash = 7;

  for (const character of value) {
    hash = (hash * 31 + (character.codePointAt(0) ?? 0)) % 2_147_483_647;
  }

  return hash;
};

const getDimensions = (path: string) => {
  if (/(?:avatar|user|headshot)/i.test(path)) {
    return [160, 160] as const;
  }
  if (/(?:logo|insignia)/i.test(path)) {
    return [320, 96] as const;
  }
  if (/(?:badge-app|badge-google)/i.test(path)) {
    return [260, 80] as const;
  }
  if (/(?:icon|btc|eth)/i.test(path)) {
    return [64, 64] as const;
  }
  if (/(?:portrait|member|team)/i.test(path)) {
    return [600, 800] as const;
  }
  if (/(?:square|product|shopping-cart)/i.test(path)) {
    return [700, 700] as const;
  }
  if (/(?:hero|footer|background|bg-|overlay|full-width)/i.test(path)) {
    return [1200, 700] as const;
  }
  if (/(?:strip|landscape|bento|category-preview)/i.test(path)) {
    return [800, 520] as const;
  }

  return [800, 600] as const;
};

const getLabel = (path: string) => {
  const fileName = path.split("/").at(-1) ?? "emailcn";

  return fileName
    .replace(/\.[^.]+$/, "")
    .replace(/^(?:logo|badge|icon)-/, "")
    .replaceAll("-", " ")
    .replaceAll(/\b\w/g, (character) => character.toUpperCase());
};

const getSeed = (path: string) =>
  `emailcn-${path
    .replace(/\.[^.]+$/, "")
    .replaceAll(/[^a-z0-9]+/gi, "-")
    .replaceAll(/^-|-$/g, "")
    .toLowerCase()}`;

export const emailAsset = (path: string) => {
  const normalizedPath = path.replace(/^\/+/, "");

  if (
    normalizedPath === "bento-grids/trend.png" ||
    normalizedPath === "bento-grids/trend-sm.png"
  ) {
    return `${ASSET_ORIGIN}/email-assets/${normalizedPath}`;
  }

  const seed = getSeed(normalizedPath);
  const hash = hashString(seed);
  const [background, foreground] =
    palettes[hash % palettes.length] ?? palettes[0];
  const [width, height] = getDimensions(normalizedPath);

  if (/(?:avatar|user|headshot|member|team)/i.test(normalizedPath)) {
    return `https://api.dicebear.com/9.x/lorelei/png?seed=${encodeURIComponent(
      seed
    )}&size=${Math.max(width, height)}&backgroundColor=${background.toLowerCase()}`;
  }

  if (/(?:trend|chart)/i.test(normalizedPath)) {
    return `${ASSET_ORIGIN}/email-assets/bento-grids/trend.png`;
  }

  if (
    /(?:icon|btc|eth|logo|insignia|badge-app|badge-google)/i.test(
      normalizedPath
    )
  ) {
    return `https://placehold.co/${width}x${height}/${background}/${foreground}.png?text=${encodeURIComponent(
      getLabel(normalizedPath)
    )}`;
  }

  return `https://picsum.photos/seed/${encodeURIComponent(
    seed
  )}/${width}/${height}.jpg`;
};
